<?php
declare(strict_types=1);
$keyword=str_replace('-',' ',trim((string)($_GET['keyword']??'')));$locationSlug=trim((string)($_GET['location']??''));$location=ucwords(str_replace('-',' ',$locationSlug));
$title=ucwords($keyword).' Jobs'.($location?' in '.$location:'').' | JobsOther';
$desc='Browse the latest '.($keyword?:'job').' opportunities'.($location?' in '.$location:'').' and apply online.';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($title)?></title><meta name="description" content="<?=htmlspecialchars($desc)?>"><link rel="canonical" href="https://jobsother.com/jobs/<?=rawurlencode(trim(str_replace(' ','-',strtolower($keyword))))?>/<?=rawurlencode($locationSlug)?>"><style>body{font-family:Arial,sans-serif;margin:0;background:#f7f8fa;color:#202733}.wrap{max-width:900px;margin:auto;padding:24px}.card{background:#fff;border:1px solid #ddd;border-radius:12px;padding:20px;margin-bottom:12px}a{color:#d8610d;text-decoration:none}</style></head><body><div class="wrap"><p><a href="/">JobsOther</a></p><h1><?=htmlspecialchars(ucwords($keyword))?> Jobs<?= $location?' in '.htmlspecialchars($location):'' ?></h1><p><?=htmlspecialchars($desc)?></p><div id="jobs"><p>Loading jobs…</p></div></div><script>
const q=<?=json_encode($keyword)?>,loc=<?=json_encode($location)?>;fetch('/api/jobs.php?q='+encodeURIComponent(q)+'&location='+encodeURIComponent(loc)+'&results_per_page=20').then(r=>r.json()).then(d=>{document.getElementById('jobs').innerHTML=(d.results||[]).map(j=>'<div class="card"><h2><a href="/job.html?id='+encodeURIComponent(j.id)+'&q='+encodeURIComponent(q)+'&location='+encodeURIComponent(loc)+'">'+String(j.title).replace(/[<>]/g,'')+'</a></h2><strong>'+String(j.company||'').replace(/[<>]/g,'')+'</strong><p>'+String(j.location||'').replace(/[<>]/g,'')+'</p><p>'+String(j.description||'').replace(/[<>]/g,'').slice(0,220)+'…</p></div>').join('')||'<p>No jobs found.</p>'});
</script></body></html>